messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/libtests/pngvalid.c
Line: 1774
Function: store_memory_free
Bug type: out-of-bounds-read
CWE: CWE-125
Explanation: When freeing, the code validates the trailing marker via memcmp((png_byte *)(memory+1)+cb, pool->mark, sizeof pool->mark). If the earlier allocation in store_malloc suffered an integer overflow resulting in a too-small allocation, this memcmp reads beyond the allocated block, causing an out-of-bounds read.

Source context:
```c
     1734:  * libpng struct is non-NULL, else it outputs a message and returns.  This means
     1735:  * that a memory problem while libpng is running will abort (png_error) the
     1736:  * handling of particular file while one in cleanup (after the destroy of the
     1737:  * struct has returned) will simply keep going and free (or attempt to free)
     1738:  * all the memory.
     1739:  */
     1740: static void
     1741: store_pool_error(png_store *ps, const png_struct *pp, const char *msg)
     1742: {
     1743:    if (pp != NULL)
     1744:       png_error(pp, msg);
     1745: 
     1746:    /* Else we have to do it ourselves.  png_error eventually calls store_log,
     1747:     * above.  store_log accepts a NULL png_struct* - it just changes what gets
     1748:     * output by store_message.
     1749:     */
     1750:    store_log(ps, pp, msg, 1 /* error */);
     1751: }
     1752: 
     1753: static void
     1754: store_memory_free(const png_struct *pp, store_pool *pool, store_memory *memory)
     1755: {
     1756:    /* Note that pp may be NULL (see store_pool_delete below), the caller has
     1757:     * found 'memory' in pool->list *and* unlinked this entry, so this is a valid
     1758:     * pointer (for sure), but the contents may have been trashed.
     1759:     */
     1760:    if (memory->pool != pool)
     1761:       store_pool_error(pool->store, pp, "memory corrupted (pool)");
     1762: 
     1763:    else if (memcmp(memory->mark, pool->mark, sizeof memory->mark) != 0)
     1764:       store_pool_error(pool->store, pp, "memory corrupted (start)");
     1765: 
     1766:    /* It should be safe to read the size field now. */
     1767:    else
     1768:    {
     1769:       png_alloc_size_t cb = memory->size;
     1770: 
     1771:       if (cb > pool->max)
     1772:          store_pool_error(pool->store, pp, "memory corrupted (size)");
     1773: 
>>>  1774:       else if (memcmp((png_byte *)(memory+1)+cb, pool->mark, sizeof pool->mark)
     1775:          != 0)
     1776:          store_pool_error(pool->store, pp, "memory corrupted (end)");
     1777: 
     1778:       /* Finally give the library a chance to find problems too: */
     1779:       else
     1780:          {
     1781:          pool->current -= cb;
     1782:          free(memory);
     1783:          }
     1784:    }
     1785: }
     1786: 
     1787: static void
     1788: store_pool_delete(png_store *ps, store_pool *pool)
     1789: {
     1790:    if (pool->list != NULL)
     1791:    {
     1792:       fprintf(stderr, "%s: %s %s: memory lost (list follows):\n", ps->test,
     1793:          pool == &ps->read_memory_pool ? "read" : "write",
     1794:          pool == &ps->read_memory_pool ? (ps->current != NULL ?
     1795:             ps->current->name : "unknown file") : ps->wname);
     1796:       ++ps->nerrors;
     1797: 
     1798:       do
     1799:       {
     1800:          store_memory *next = pool->list;
     1801:          pool->list = next->next;
     1802:          next->next = NULL;
     1803: 
     1804:          fprintf(stderr, "\t%lu bytes @ %p\n",
     1805:              (unsigned long)next->size, (const void*)(next+1));
     1806:          /* The NULL means this will always return, even if the memory is
     1807:           * corrupted.
     1808:           */
     1809:          store_memory_free(NULL, pool, next);
     1810:       }
     1811:       while (pool->list != NULL);
     1812:    }
     1813: 
     1814:    /* And reset the other fields too for the next time. */
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libpng_upstream reproducer.c -L/tmp/libpng_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libpng_upstream
